export const tutorial = { id: "rc-button", title: "Button 按钮", steps: [
    { ...{"id":"step-1","title":"六种外观","goal":"直接比较六种按钮外观及各自适用的操作层级。","why":"填充、浅阴影、虚线与文字强调表达不同优先级；危险操作使用独立的语义颜色。","instruction":"对比六个示例，悬停和点击按钮，再用 Tab 查看键盘焦点。","expected":"六种外观同时可见，点击后显示对应的 appearance；示例只更新本地提示。","changes":["同时展示 primary、subtle、dashed、text、link 和 danger。","每种外观配有中文名称、属性值和用途说明。"],"sourceCode":"import { useState } from \"react\";\nimport { css } from \"@crab-dev/css\";\nimport token from \"@crab-dev/rc-token-semantic\";\nimport Button, { type ButtonProps } from \"@crab-dev/rc-button\";\n\nconst stackStyle = css`display: grid; gap: ${token.space[\"section-gap\"]}; min-width: 0;`;\nconst gridStyle = css`\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(min(100%, calc(${token.space[\"group-gap\"]} * 9)), 1fr));\n    gap: ${token.space[\"section-gap\"]};\n`;\nconst cardStyle = css`\n    display: grid;\n    grid-template-rows: auto 1fr auto;\n    justify-items: start;\n    gap: ${token.space[\"component-gap\"]};\n    min-width: 0;\n    padding: ${token.space[\"section-gap\"]};\n    border: 1px solid ${token.color.border.subtle};\n    border-radius: ${token.radius.lg};\n    background: ${token.color.background.surface};\n`;\nconst noteStyle = css`margin: 0; color: ${token.color.text.secondary}; font-size: ${token.font.size.body};`;\nconst feedbackStyle = css`\n    padding: ${token.space[\"component-gap\"]} ${token.space[\"control-padding-x\"]};\n    border-radius: ${token.radius.md};\n    background: ${token.color.background.sunken};\n    color: ${token.color.text.secondary};\n    font-size: ${token.font.size.body};\n`;\nconst appearances = [\n    { value: \"primary\", label: \"主要按钮\", hint: \"高强调度，用于保存、提交等主操作。\" },\n    { value: \"subtle\", label: \"常规按钮\", hint: \"默认外观，中性表面与浅阴影，悬停时显现品牌色，用于取消、返回和工具栏操作。\" },\n    { value: \"dashed\", label: \"虚线按钮\", hint: \"虚线描边，用于添加条件、新增内容。\" },\n    { value: \"text\", label: \"文字按钮\", hint: \"低强调度，用于工具栏和轻量操作。\" },\n    { value: \"link\", label: \"链接样式\", hint: \"文字强调；需要导航时再传入 href。\" },\n    { value: \"danger\", label: \"危险按钮\", hint: \"使用错误色，提示删除、清空等操作。\" },\n] satisfies Array<{ value: NonNullable<ButtonProps[\"appearance\"]>; label: string; hint: string }>;\n\nexport default function Example() {\n    const [message, setMessage] = useState(\"点击任意按钮查看反馈，也可以用 Tab 观察焦点。这里只演示外观。\");\n    return (\n        <div className={stackStyle}>\n            <div className={gridStyle}>\n                {appearances.map(item => (\n                    <section key={item.value} className={cardStyle} aria-label={`${item.label}外观`}>\n                        <strong>{item.label} · <code>{item.value}</code></strong>\n                        <p className={noteStyle}>{item.hint}</p>\n                        <Button appearance={item.value} onClick={() => setMessage(`已点击「${item.label}」，appearance=\"${item.value}\"。`)}>\n                            {item.label}\n                        </Button>\n                    </section>\n                ))}\n            </div>\n            <output className={feedbackStyle} aria-live=\"polite\">{message}</output>\n        </div>\n    );\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-button/step-1.js") } },
    { ...{"id":"step-2","title":"连接交互状态","goal":"让按钮响应点击，并切换外观","why":"用 React 状态分别管理保存次数和按钮外观，让两种变化互不干扰。","instruction":"点击保存两次，再切换按钮外观。","expected":"保存次数变为 2；外观变化不会清空计数。","changes":["新增 count 状态，在 onClick 中递增。","新增 primary 状态，通过 appearance 切换主次外观。"],"sourceCode":"import { useState } from \"react\";\nimport Button from \"@crab-dev/rc-button\";\n\nexport default function Example() {\n    const [count, setCount] = useState(0);\n    const [primary, setPrimary] = useState(true);\n    return (\n        <>\n            <Button\n                appearance={primary ? \"primary\" : \"subtle\"}\n                onClick={() => setCount((value) => value + 1)}\n            >\n                保存资料\n            </Button>\n            <p>\n                <output aria-live=\"polite\">已保存 {count} 次</output>\n            </p>\n            <Button onClick={() => setPrimary((value) => !value)}>切换按钮外观</Button>\n        </>\n    );\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-button/step-2.js") } },
    { ...{"id":"step-3","title":"尺寸对照","goal":"同时查看三种尺寸在六种外观下的效果。","why":"直接并排展示 small、middle 和 large，便于比较高度、内边距与字号。","instruction":"纵向比较三行尺寸，横向比较同一尺寸的六种外观，并点击按钮查看属性。","expected":"默认鼠标环境下，三档高度分别为 24px、32px、40px；窄屏时按钮自动换行。","changes":["通过 size 设置小、中、大三档尺寸。","保留相同的外观顺序，方便直观比较。"],"sourceCode":"import { useState } from \"react\";\nimport { css } from \"@crab-dev/css\";\nimport token from \"@crab-dev/rc-token-semantic\";\nimport Button, { type ButtonProps } from \"@crab-dev/rc-button\";\n\nconst stackStyle = css`display: grid; gap: ${token.space[\"group-gap\"]}; min-width: 0;`;\nconst sectionStyle = css`\n    display: grid;\n    gap: ${token.space[\"component-gap\"]};\n    padding-bottom: ${token.space[\"section-gap\"]};\n    border-bottom: 1px solid ${token.color.border.subtle};\n`;\nconst rowStyle = css`display: flex; flex-wrap: wrap; align-items: center; gap: ${token.space[\"component-gap\"]};`;\nconst noteStyle = css`margin: 0; color: ${token.color.text.secondary}; font-size: ${token.font.size.body};`;\nconst sizes = [\n    { value: \"small\", label: \"小号\", height: \"24px\", description: \"紧凑工具栏、表格内操作。\" },\n    { value: \"middle\", label: \"中号（默认）\", height: \"32px\", description: \"普通表单和页面操作。\" },\n    { value: \"large\", label: \"大号\", height: \"40px\", description: \"需要更醒目的独立操作。\" },\n] satisfies Array<{ value: NonNullable<ButtonProps[\"size\"]>; label: string; height: string; description: string }>;\nconst appearances = [\"primary\", \"subtle\", \"dashed\", \"text\", \"link\", \"danger\"] satisfies Array<NonNullable<ButtonProps[\"appearance\"]>>;\n\nexport default function Example() {\n    const [message, setMessage] = useState(\"同一列外观一致，横向对比不同外观，纵向对比尺寸。\");\n    return (\n        <div className={stackStyle}>\n            {sizes.map(size => (\n                <section key={size.value} className={sectionStyle} aria-label={`${size.value} 尺寸对照`}>\n                    <strong>{size.label} · <code>{size.value}</code> · {size.height}</strong>\n                    <p className={noteStyle}>{size.description}</p>\n                    <div className={rowStyle}>\n                        {appearances.map(appearance => (\n                            <Button key={appearance} size={size.value} appearance={appearance}\n                                onClick={() => setMessage(`当前体验：size=\"${size.value}\"，appearance=\"${appearance}\"。`)}>\n                                {appearance}\n                            </Button>\n                        ))}\n                    </div>\n                </section>\n            ))}\n            <p className={noteStyle}>以上为默认鼠标环境下的高度；触控环境会扩展命中区域。</p>\n            <output className={noteStyle} aria-live=\"polite\">{message}</output>\n        </div>\n    );\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-button/step-3.js") } },
    { ...{"id":"step-4","title":"图标与组合","goal":"查看前后置图标、纯图标、圆形、选中按钮组和通栏按钮。","why":"图标位置、按钮形状与容器宽度决定按钮如何融入表单和工具栏。","instruction":"点击图标按钮，切换粗体、斜体和下划线；比较三个圆形尺寸，体验通栏按钮和 API 链接。","expected":"每个可用按钮都有反馈；按钮组独立保留多个选中项，通栏按钮撑满当前容器。","changes":["使用 icon、iconAfter、shape 与 aria-label。","使用 ButtonGroup、isSelected、shouldFitContainer 和 href。"],"sourceCode":"import { useState } from \"react\";\nimport { css } from \"@crab-dev/css\";\nimport token from \"@crab-dev/rc-token-semantic\";\nimport Button, { ButtonGroup } from \"@crab-dev/rc-button\";\n\nconst stackStyle = css`display: grid; gap: ${token.space[\"group-gap\"]}; min-width: 0;`;\nconst sectionStyle = css`display: grid; gap: ${token.space[\"component-gap\"]}; min-width: 0;`;\nconst rowStyle = css`display: flex; flex-wrap: wrap; align-items: center; gap: ${token.space[\"component-gap\"]};`;\nconst noteStyle = css`margin: 0; color: ${token.color.text.secondary}; font-size: ${token.font.size.body};`;\n\nfunction PlusIcon() {\n    return <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M12 5v14M5 12h14\" /></svg>;\n}\nfunction ArrowIcon() {\n    return <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" aria-hidden=\"true\" focusable=\"false\"><path d=\"m9 5 7 7-7 7M4 12h12\" /></svg>;\n}\n\nexport default function Example() {\n    const [bold, setBold] = useState(false);\n    const [italic, setItalic] = useState(true);\n    const [underline, setUnderline] = useState(false);\n    const [message, setMessage] = useState(\"点击按钮查看反馈；格式按钮可以独立切换选中状态。\");\n    return (\n        <div className={stackStyle}>\n            <section className={sectionStyle} aria-label=\"图标位置\">\n                <strong>图标与文字</strong>\n                <p className={noteStyle}>icon 放在文字前，iconAfter 放在文字后。</p>\n                <div className={rowStyle}>\n                    <Button appearance=\"primary\" icon={<PlusIcon />} onClick={() => setMessage(\"已点击前置图标按钮。\")}>新建项目</Button>\n                    <Button iconAfter={<ArrowIcon />} onClick={() => setMessage(\"已点击后置图标按钮。\")}>下一步</Button>\n                    <Button appearance=\"text\" icon={<PlusIcon />} onClick={() => setMessage(\"已点击轻量图标按钮。\")}>添加条件</Button>\n                </div>\n            </section>\n            <section className={sectionStyle} aria-label=\"纯图标与圆形按钮\">\n                <strong>纯图标与圆形</strong>\n                <p className={noteStyle}>纯图标按钮通过 aria-label 提供名称；圆形按钮宽高相等。</p>\n                <div className={rowStyle}>\n                    <Button icon={<PlusIcon />} aria-label=\"方形新增\" onClick={() => setMessage(\"已点击方形新增。\")}/>\n                    <Button appearance=\"primary\" shape=\"circle\" size=\"small\" icon={<PlusIcon />} aria-label=\"小号圆形新增\" onClick={() => setMessage(\"已点击小号圆形新增。\")}/>\n                    <Button appearance=\"primary\" shape=\"circle\" icon={<PlusIcon />} aria-label=\"中号圆形新增\" onClick={() => setMessage(\"已点击中号圆形新增。\")}/>\n                    <Button appearance=\"primary\" shape=\"circle\" size=\"large\" icon={<PlusIcon />} aria-label=\"大号圆形新增\" onClick={() => setMessage(\"已点击大号圆形新增。\")}/>\n                    <Button shape=\"circle\" icon={<PlusIcon />} aria-label=\"禁用圆形新增\" disabled />\n                </div>\n            </section>\n            <section className={sectionStyle} aria-label=\"按钮组选中状态\">\n                <strong>按钮组与选中</strong>\n                <p className={noteStyle}>ButtonGroup 统一尺寸和外观，isSelected 显示可切换状态。</p>\n                <ButtonGroup size=\"middle\" appearance=\"subtle\">\n                    <Button isSelected={bold} onClick={() => setBold(value => !value)}>粗体</Button>\n                    <Button isSelected={italic} onClick={() => setItalic(value => !value)}>斜体</Button>\n                    <Button isSelected={underline} onClick={() => setUnderline(value => !value)}>下划线</Button>\n                </ButtonGroup>\n                <output className={noteStyle} aria-live=\"polite\">已选格式：{[bold && \"粗体\", italic && \"斜体\", underline && \"下划线\"].filter(Boolean).join(\"、\") || \"无\"}</output>\n            </section>\n            <section className={sectionStyle} aria-label=\"通栏按钮\">\n                <strong>通栏与链接</strong>\n                <p className={noteStyle}>shouldFitContainer 撑满容器；href 让按钮承担实际导航。</p>\n                <Button appearance=\"primary\" shouldFitContainer onClick={() => setMessage(\"已点击通栏按钮。\")}>继续下一步</Button>\n                <div className={rowStyle}><Button appearance=\"link\" href=\"#api\">查看 Button API</Button></div>\n            </section>\n            <output className={noteStyle} aria-live=\"polite\">{message}</output>\n        </div>\n    );\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-button/step-4.js") } },
    { ...{"id":"step-5","title":"状态与明暗主题","goal":"在明暗背景上对照默认、禁用、加载和选中，并比较常规按钮与主按钮的搭配。","why":"主题变化时，按钮的操作层级、可读性、表面层次与状态反馈都需要保持清楚。","instruction":"切换紫、蓝、绿品牌色；悬停、按压或用 Tab 聚焦常规按钮，切换选中状态，再点击保存、取消与工具栏操作。","expected":"常规按钮默认使用浅阴影；悬停时阴影增强、按压时收回，交互显现品牌色，选中使用无阴影的强填充；主操作保持醒目，禁用和加载不触发操作。","changes":["用 ConfigProvider 同时展示 light 和 dark，保持按钮本身的 appearance 一致。","并列展示 disabled、loading、isSelected，以及保存 + 取消和主要操作 + 工具栏操作。"],"sourceCode":"import { useState } from \"react\";\nimport { css } from \"@crab-dev/css\";\nimport token from \"@crab-dev/rc-token-semantic\";\nimport Button, { type ButtonProps } from \"@crab-dev/rc-button\";\nimport ConfigProvider from \"@crab-dev/rc-config-provider\";\n\nconst stackStyle = css`display: grid; gap: ${token.space[\"section-gap\"]}; min-width: 0;`;\nconst rowStyle = css`display: flex; flex-wrap: wrap; align-items: center; gap: ${token.space[\"component-gap\"]};`;\nconst panelsStyle = css`\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(min(100%, calc(${token.space[\"group-gap\"]} * 15)), 1fr));\n    gap: ${token.space[\"section-gap\"]};\n`;\nconst panelStyle = css`\n    min-width: 0;\n    padding: ${token.space[\"section-gap\"]};\n    background: ${token.color.background.surface};\n    color: ${token.color.text.primary};\n    border: 1px solid ${token.color.border.subtle};\n    border-radius: ${token.radius.lg};\n`;\nconst variantStyle = css`\n    display: grid;\n    gap: ${token.space[\"component-gap\"]};\n    padding-top: ${token.space[\"section-gap\"]};\n    border-top: 1px solid ${token.color.border.subtle};\n`;\nconst statesStyle = css`\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(min(100%, calc(${token.space[\"component-gap\"]} * 11)), 1fr));\n    gap: ${token.space[\"component-gap\"]};\n`;\nconst sampleStyle = css`display: grid; justify-items: start; align-content: start; gap: ${token.space[\"component-gap\"]};`;\nconst noteStyle = css`margin: 0; color: ${token.color.text.secondary}; font-size: ${token.font.size.caption};`;\nconst appearances = [\"primary\", \"subtle\", \"dashed\", \"text\", \"link\", \"danger\"] satisfies Array<NonNullable<ButtonProps[\"appearance\"]>>;\n\nfunction ThemePanel({ theme, brandColor }: { theme: \"light\" | \"dark\"; brandColor: string }) {\n    const [message, setMessage] = useState(\"悬停或用 Tab 聚焦可用按钮，观察颜色、阴影与焦点环。\");\n    const [selected, setSelected] = useState(true);\n    const title = theme === \"light\" ? \"浅色\" : \"深色\";\n    return (\n        <ConfigProvider theme={theme} brandColor={brandColor} className={panelStyle}>\n            <section className={stackStyle} aria-label={`${title} Button 状态对照`}>\n                <strong>{title}主题</strong>\n                {appearances.map(appearance => (\n                    <section key={appearance} className={variantStyle} aria-label={`${title} ${appearance}`}>\n                        <strong><code>{appearance}</code></strong>\n                        <div className={statesStyle}>\n                            <div className={sampleStyle}>\n                                <span className={noteStyle}>默认</span>\n                                <Button appearance={appearance} onClick={() => setMessage(`已点击 ${title}主题下的 ${appearance} 按钮。`)}>按钮</Button>\n                            </div>\n                            <div className={sampleStyle}>\n                                <span className={noteStyle}>禁用</span>\n                                <Button appearance={appearance} disabled>按钮</Button>\n                            </div>\n                            <div className={sampleStyle}>\n                                <span className={noteStyle}>加载中</span>\n                                <Button appearance={appearance} loading>按钮</Button>\n                            </div>\n                            {appearance === \"subtle\" && (\n                                <div className={sampleStyle}>\n                                    <span className={noteStyle}>可切换选中</span>\n                                    <Button isSelected={selected} onClick={() => setSelected(value => !value)}>{selected ? \"已选中\" : \"未选中\"}</Button>\n                                </div>\n                            )}\n                        </div>\n                    </section>\n                ))}\n                <section className={variantStyle} aria-label={`${title} 表单操作`}>\n                    <strong>保存 + 取消</strong>\n                    <p className={noteStyle}>保存用实色强调；取消使用中性表面与浅阴影，悬停时显现品牌色。</p>\n                    <div className={rowStyle}>\n                        <Button appearance=\"primary\" onClick={() => setMessage(`${title}：已保存本地示例。`)}>保存修改</Button>\n                        <Button onClick={() => setMessage(`${title}：已取消本地编辑。`)}>取消</Button>\n                    </div>\n                </section>\n                <section className={variantStyle} aria-label={`${title} 工具栏操作`}>\n                    <strong>主要操作 + 工具栏操作</strong>\n                    <p className={noteStyle}>新建最醒目；刷新与导出保持中性，操作时提供同色系反馈。</p>\n                    <div className={rowStyle}>\n                        <Button appearance=\"primary\" onClick={() => setMessage(`${title}：已新建本地示例项目。`)}>新建项目</Button>\n                        <Button onClick={() => setMessage(`${title}：已刷新本地示例。`)}>刷新</Button>\n                        <Button onClick={() => setMessage(`${title}：已模拟导出，不下载文件。`)}>导出</Button>\n                    </div>\n                </section>\n                <output className={noteStyle} aria-live=\"polite\">{message}</output>\n            </section>\n        </ConfigProvider>\n    );\n}\n\nexport default function Example() {\n    const [brandColor, setBrandColor] = useState(\"#6750a4\");\n    return (\n        <div className={stackStyle}>\n            <div className={rowStyle} role=\"group\" aria-label=\"Button 品牌色\">\n                <span>品牌色</span>\n                {[[\"紫色\", \"#6750a4\"], [\"蓝色\", \"#1677ff\"], [\"绿色\", \"#087f5b\"]].map(([name, color]) => (\n                    <Button key={color} size=\"small\" isSelected={brandColor === color} onClick={() => setBrandColor(color)}>{name}</Button>\n                ))}\n            </div>\n            <p className={noteStyle}>六种外观对照默认、禁用和加载；常规按钮另含可切换的选中状态。常规按钮使用中性表面与浅阴影，悬停时阴影略微增强，按压时收回；交互时显现品牌色，选中使用无阴影的强填充。加载项持续显示；危险色保持独立语义。</p>\n            <div className={panelsStyle}>\n                <ThemePanel theme=\"light\" brandColor={brandColor} />\n                <ThemePanel theme=\"dark\" brandColor={brandColor} />\n            </div>\n        </div>\n    );\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-button/step-5.js") } }
] } satisfies TutorialRecord;
